  sheet.getRange('C4:D6').setBackground('#EDF2F7').setBorder(true, true, true, true, false, false, '#CBD5E0', SpreadsheetApp.BorderStyle.SOLID);

  // Card 3: Top 5 (30y) Post-Liq CAGR (Cols E-F)
